$path=Resolve-Path 'wwwroot/app.js'
$source=[IO.File]::ReadAllText($path,[Text.Encoding]::UTF8)
$replacement=@'
function openDetail(id){const x=items.find(i=>i.id===id);if(!x)return;const image=x.assets?.find(a=>a.kind==='image'),model=x.assets?.find(a=>a.kind==='model'),pdf=x.assets?.find(a=>a.kind==='drawing'),url=a=>`/files/${encodeURIComponent(a.storedName)}`,order=(window.__orders||[]).find(o=>o.number===x.orderNumber),park=order?.parkName||'';const content=`<div class="modal-content"><section class="document-render">${image?`<img src="${url(image)}" alt="${esc(x.name)}">`:'<div class="image-placeholder">\u0420\u0435\u043d\u0434\u0435\u0440 \u043d\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d</div>'}<div class="render-caption">\u0420\u0415\u041d\u0414\u0415\u0420 \u00b7 ${esc(x.number)}</div></section><div class="product-document"><div class="document-heading"><div><div class="detail-category">${esc(x.category)}</div><h2 class="detail-number">${esc(x.name)}</h2><div class="detail-name">\u0417\u0430\u043a\u0430\u0437 \u2116 ${esc(x.orderNumber||'\u2014')}${park?` \u00b7 ${esc(park)}`:''} \u00b7 \u0438\u0437\u0434\u0435\u043b\u0438\u0435 \u2116 ${esc(x.productNumber||'\u2014')}</div><div class="dimensions-block"><span>\u0413\u0430\u0431\u0430\u0440\u0438\u0442\u044b</span><b>${esc(x.dimensions||'\u2014')} \u043c\u043c</b></div></div><div class="document-actions">${model?`<a class="button primary" href="${url(model)}" target="_blank" rel="noopener">\u25c9 3D</a>`:''}${pdf?`<a class="button" href="${url(pdf)}" download="${esc(pdf.name)}">\u2193 \u0421\u043a\u0430\u0447\u0430\u0442\u044c PDF</a>`:''}${editing?'<button class="button" id="editDetails">\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c</button>':''}</div></div>${x.notes?`<div class="document-notes"><b>\u041f\u0440\u0438\u043c\u0435\u0447\u0430\u043d\u0438\u0435</b><div>${esc(x.notes)}</div></div>`:''}${pdf?`<section class="drawing-page"><div class="drawing-toolbar"><span>\u0427\u0415\u0420\u0422\u0401\u0416 \u00b7 ${esc(pdf.name)}</span><span id="pdfPageLabel">\u0421\u0442\u0440\u0430\u043d\u0438\u0446\u0430 1</span><a href="${url(pdf)}" download="${esc(pdf.name)}">\u2193 \u0421\u043a\u0430\u0447\u0430\u0442\u044c PDF</a></div><div class="pdf-viewer"><button class="pdf-nav prev" id="pdfPrev">\u2039</button><canvas id="pdfCanvas"></canvas><button class="pdf-nav next" id="pdfNext">\u203a</button></div></section>`:'<div class="no-drawing">PDF-\u0447\u0435\u0440\u0442\u0451\u0436 \u043d\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d.</div>'}${editing?`<div class="replace-files"><div class="section-label">\u0424\u0430\u0439\u043b\u044b \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438</div><div>${(x.assets||[]).map(a=>`<div class="asset-manage"><span>${esc(a.kind)} \u00b7 ${esc(a.name)}</span><button class="delete-asset" data-remove="${a.id}">\u0423\u0434\u0430\u043b\u0438\u0442\u044c</button></div>`).join('')}</div><div class="upload-row"><input type="file" id="moreFiles" multiple accept=".html,.htm,.pdf,image/*"><button class="button primary" id="uploadMore">\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0444\u0430\u0439\u043b\044b</button></div></div>`:''}</div></div>`;modal(`${esc(x.number)} \u00b7 ${esc(x.name)}`,`${esc(x.category)} \u00b7 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u0438\u0437\0434\u0435\u043b\u0438\u044f`,content,`<footer class="modal-actions"><span>${x.sourcePath?'<button class="button" id="copyPath">\u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0435\u0442\u0435\u0432\u043e\u0439 \u043f\u0443\u0442\u044c</button>':''}</span><button class="button" id="closeDetail">\u0417\u0430\u043a\0440\u044b\u0442\u044c</button></footer>`,'product-detail-modal');$('#closeDetail').onclick=closeModal;if(editing)$('#editDetails').onclick=()=>editor(x);if(x.sourcePath)$('#copyPath').onclick=()=>navigator.clipboard.writeText(x.sourcePath).then(()=>toast('\u041f\u0443\u0442\u044c \u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d'));if(pdf)renderPdf(url(pdf));root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(confirm('\u0423\u0434\0430\u043b\u0438\u0442\u044c \u0444\u0430\u0439\u043b?')){await api(`/api/items/${x.id}/files/${b.dataset.remove}`,{method:'DELETE'});await refresh();openDetail(x.id)}});if(editing)$('#uploadMore').onclick=async()=>{for(const f of $('#moreFiles').files){const fd=new FormData();fd.append('file',f);await api(`/api/items/${x.id}/files`,{method:'POST',body:fd})}await refresh();openDetail(x.id)}}
'@
$start=$source.IndexOf('function openDetail(id)')
$finish=$source.IndexOf('function renderPdf', $start)
if($start -lt 0 -or $finish -lt 0){throw 'openDetail not found'}
$source=$source.Substring(0,$start)+$replacement.Trim()+"`r`n"+$source.Substring($finish)
[IO.File]::WriteAllText($path,$source,[Text.UTF8Encoding]::new($false))
